import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Sidebar from "../../components/Sidebar";

export default function HumanGeography() {
  const [sub, setSub] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lessons, setLessons] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    async function load() {
      try {
        const res = await fetch("http://localhost:8080/resources");
        const data = await res.json();
        const found = (data.subsciences || []).find((s) => /geo/i.test(s.name) || /human.*geo/i.test(s.name) || s.code === "human_geography");
        setSub(found || null);
        await loadLessons(found);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    }
    load();
    async function loadLessons(found) {
      if (!found) {
        const pad = [];
        for (let i = 1; i <= 10; i++) pad.push({ id: `local-${i}`, lesson_number: i, title: `Lesson ${i}`, status: "schedule_locked" });
        setLessons(pad);
        return;
      }

      try {
        const uid = JSON.parse(localStorage.getItem("user"))?.id || "";
        const lres = await fetch(`http://localhost:8080/subsciences/${found.id}/lessons/${uid}`);
        const ldata = await lres.json();
        const fetched = ldata.lessons || [];

        const visitedKey = `visited_sub_${found.id}_user_${uid || "guest"}`;
        const firstVisit = !localStorage.getItem(visitedKey);

        const pad = [];
        for (let i = 1; i <= 10; i++) {
          const ex = fetched.find((f) => f.lesson_number === i);
          if (firstVisit) pad.push(ex ? { ...ex, status: "locked" } : { id: `local-${i}`, lesson_number: i, title: `Lesson ${i}`, status: "locked" });
          else pad.push(ex || { id: `local-${i}`, lesson_number: i, title: `Lesson ${i}`, status: "locked" });
        }

        if (firstVisit) localStorage.setItem(visitedKey, Date.now().toString());
        setLessons(pad);
      } catch (e) {
        const pad = [];
        for (let i = 1; i <= 10; i++) pad.push({ id: `local-${i}`, lesson_number: i, title: `Lesson ${i}`, status: "locked" });
        setLessons(pad);
      }
    }

    loadLessons(found);
  }, []);

  function viewLesson(lesson) {
    navigate(`/lesson/${lesson.id}`, { state: { lesson, subId: sub?.id } });
  }

  return (
    <div className="dashboard-page">
      <Sidebar />
      <main className="dashboard-main">
        <header className="dashboard-header">
          <div>
            <h1>Human Geography</h1>
            <p className="dashboard-subtitle">Study how humans interact with environments and places.</p>
          </div>
        </header>

        {loading ? (
          <p className="dashboard-loading">Loading...</p>
        ) : (
          <div>
            {!sub && (
              <div className="card" style={{ marginBottom: 12 }}>
                <p className="muted">
                  No resources selected for this unit — lessons are schedule-locked.
                  <button className="btn" onClick={() => navigate("/resources")} style={{ marginLeft: 8 }}>
                    Select Resources
                  </button>
                </p>
              </div>
            )}

            {sub && (
              <div className="card" style={{ marginBottom: 12 }}>
                <h2>{sub.name}</h2>
                <p>{sub.description || "10 lessons, tutors, games and the unit test."}</p>
                <div style={{ marginTop: 12 }}>
                  <button className="primary-btn" onClick={() => navigate(`/subscience/${sub.id}`)}>
                    Start Unit
                  </button>
                </div>
              </div>
            )}

            <section className="dashboard-panel">
              <h2>Lessons</h2>
              <ul className="subscience-lessons-list">
                {lessons.map((lesson) => (
                  <li key={lesson.id} className={`subscience-lesson ${lesson.status}`}>
                    <div className="subscience-lesson-main">
                      <div>
                        <p className="subscience-lesson-number">Lesson {lesson.lesson_number}</p>
                        <p className="subscience-lesson-title">{lesson.title}</p>
                        <p className="subscience-lesson-status">Status: {lesson.status}</p>
                      </div>

                      <div className="subscience-lesson-tags">
                        {lesson.status === "completed" && <span className="tag tag-completed">Completed</span>}
                        {lesson.status === "unlocked" && <span className="tag tag-unlocked">Ready</span>}
                        {lesson.status === "locked" && <span className="tag tag-locked">Locked</span>}
                        {lesson.status === "schedule_locked" && <span className="tag tag-locked">Schedule</span>}
                      </div>
                    </div>

                    <div className="subscience-lesson-actions">
                      <div style={{ display: "flex", gap: 8 }}>
                        <button className="lesson-action-btn" disabled={lesson.status === "locked" || lesson.status === "schedule_locked"} onClick={() => viewLesson(lesson)}>View Lesson</button>
                      </div>
                    </div>
                  </li>
                ))}
              </ul>
            </section>
          </div>
        )}
      </main>
    </div>
  );
}
